package util;import jakarta.servlet.http.*;import model.*;
public class Web5 {public static String h(Object x){return x==null?"":x.toString().replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&#39;");}public static String token(HttpSession s){String t=(String)s.getAttribute("csrf");if(t==null){t=java.util.UUID.randomUUID().toString();s.setAttribute("csrf",t);}return t;}public static void post(HttpServletRequest r){if(!"POST".equals(r.getMethod())||!token(r.getSession()).equals(r.getParameter("csrf")))throw new IllegalArgumentException("Yêu cầu không hợp lệ");}public static Customer5 customer(HttpSession s){return (Customer5)s.getAttribute("user");}}
